/// Build a set template by key (None for keys this module does not own).
pub fn build(key: &str) -> Option<GraphicDoc> {
    let info = TEMPLATES.iter().find(|t| t.key == key)?;
    let mut doc: GraphicDoc = match key {
        "set_tornado_ytd" => reference::tally(),
        "set_tornado_confirmed" => reference::confirmed(),
        "set_tornado_top_years" => tornado_history::build(false,None),
        "set_tornado_top_years__national" => tornado_history::build(true,None),
        "set_tornado_top_years__portrait" => tornado_history::build(false,Some(true)),
        "set_tornado_top_years__national_portrait" => tornado_history::build(true,Some(true)),
        "set_tornado_top_years__square" => tornado_history::build(false,Some(false)),
        "set_tornado_top_years__national_square" => tornado_history::build(true,Some(false)),
        "set_holiday_countdown" => reference::countdown(None),
        "set_holiday_countdown__portrait" => reference::countdown(Some(true)),
        "set_holiday_countdown__square" => reference::countdown(Some(false)),
        _ => show_ident::build(key).or_else(|| show_schedule::build(key)).or_else(|| sponsor_cards::build(key)).or_else(|| model_maps::build(key)).or_else(|| weather_word::build(key)).or_else(|| town_forecast_maps::build(key)).or_else(|| spc_outlook::build(key)).or_else(|| qpf::build(key)).or_else(|| hourly_charts::build(key)).or_else(|| city_forecast::build(key)).or_else(|| five_day::build(key)).or_else(|| holiday_forecast::build(key)).or_else(|| road_closures::build(key)).or_else(|| weather_ticker::build(key)).or_else(|| fire_weather::build(key)).or_else(|| relief::build(key)).or_else(|| forecast_packaging::build(key)).or_else(|| cpc::build(key)).or_else(|| heat_risk::build(key)).or_else(|| social_alert::build(key)).or_else(|| social_forecast::build(key)).or_else(|| show::build(key)).or_else(|| river_crest::build(key)).or_else(|| tornado_monthly::build(key)).or_else(|| mesoscale::build(key)).or_else(|| shelter::build(key))
            .or_else(|| safety::build(key))
            .or_else(|| cold::build(key))
            .or_else(|| comparison::build(key))
            .or_else(|| observed::build(key))
            .or_else(|| winter_alerts::build(key)).or_else(|| point_report_overlays::build(key)).or_else(|| nwps_gauges::build(key)).or_else(|| zone_overlays::build(key)).or_else(|| quakes::build(key))?,
    };
    doc.name = info.name.to_string();
    doc.category = info.category.to_string();
    doc.template = Some(key.to_string());
    Some(doc)
}

/// Fetch the data the set templates need (called every 15 minutes in the background with
/// `home` = the station's home point). Store results in this module; failures stay quiet here
/// and show as missing data in the graphics.
pub async fn refresh(home: crate::config::GeoView) {
    report_feed::refresh(home).await;
    mesoscale::refresh().await;
    tornado_history::refresh().await;
    dat_survey::refresh(home).await;
    river_crest::refresh(home).await;
    nwps_gauges::refresh(home).await;
    social_forecast::refresh(home).await;
    city_forecast::refresh(home).await;
    hourly_forecast::refresh(home).await;
    spc_outlook::refresh(home).await;
    qpf::refresh(home).await;
    model_maps::refresh(home).await;
    weather_ticker::refresh(home).await;
    heat_risk::refresh(home).await;
    cpc::refresh(home).await;
    fire_weather::refresh(home).await;
}

/// Bindings the set templates use, added after the built-in ones.
pub fn bind(b: &mut Bindings, data: &WxSnapshot, settings: &Settings) {
    reference::bind(b);
    show::bind(b);
    show_ident::bind(b, settings);
    show_schedule::bind(b, settings);
    sponsor_cards::bind(b, settings);

    social_forecast::bind(b, settings);
    city_forecast::bind(b, settings);
    weather_word::bind(b, settings);
    town_forecast_maps::bind(b, settings);
    spc_outlook::bind(b, settings);
    qpf::bind(b, settings);
    model_maps::bind(b, settings);
    hourly_charts::bind(b, settings);
    five_day::bind(b, settings);
    holiday_forecast::bind(b, settings);
    weather_ticker::bind(b, settings);
    road_closures::bind(b, settings);
    forecast_packaging::bind(b);
    relief::bind(b);
    social_alert::bind(b, data, settings);
    heat_risk::bind(b, settings);
    cpc::bind(b, settings);
    fire_weather::bind(b, settings);
    river_crest::bind(b, settings);
    nwps_gauges::bind(b, settings);
    tornado_history::bind(b,settings);
    dat_survey::bind(b, settings);
    tornado_monthly::bind(b,settings);
    mesoscale::bind(b, settings);
    shelter::bind(b, data, settings);
    comparison::bind(b, data, settings);
    observed::bind(b, data, settings);
    winter_alerts::bind(b, data, settings);
    cold::bind(b, data, settings);
    quakes::bind(b, data, settings);
}

/// Draw a `set:` county or state map into the layer's box (w × h, local transform). Returns
/// false for specs this module does not know.
#[allow(clippy::too_many_arguments)]
pub fn draw_map(
    pm: &mut Pixmap,
    glyphs: &mut GlyphCache,
    local: Transform,
    mask: Option<&Mask>,
    w: f32,
    h: f32,
    spec: &str,
    opacity: f32,
    font: &str,
) -> bool {
    qpf_canvas::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || city_forecast::draw_map(pm, local, mask, w, h, spec, opacity)
        || product_overlay::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || nwps_gauges::draw_overlay(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || zone_overlays::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || road_closures::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || icons::draw(pm, local, mask, w, h, spec, opacity)
        || board::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || tornado::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
        || quakes::draw(pm, glyphs, local, mask, w, h, spec, opacity, font)
}
